'use strict';
/* FAILED MOVE BUY — QUALITY OPTIMIZER, research only.
Goal: raise WR by removing bad setups, not by merely shrinking TP.
DEV=75%, HOLD untouched. Causal features only. Entry next M5 open.
Filters: impulse size/body, reclaim, reversal candle body/close position, ATR regime, UTC hour. RR 1/1.25/1.5. One open trade/model.
*/
const fs=require('fs'),F='data/xauusd-m5-dukascopy.json',z=JSON.parse(fs.readFileSync(F,'utf8')),q=Array.isArray(z)?z:(z.candles||z.data||[]);const M=q.map(x=>({t:+new Date(x.t||x.time||x.timestamp),o:+(x.o??x.open),h:+(x.h??x.high),l:+(x.l??x.low),c:+(x.c??x.close)})).filter(x=>Number.isFinite(x.t+x.o+x.h+x.l+x.c)).sort((a,b)=>a.t-b.t),N=M.length,S=Math.floor(N*.75);
function atr(n=14){let a=Array(N).fill(null),tr=M.map((b,i)=>i?Math.max(b.h-b.l,Math.abs(b.h-M[i-1].c),Math.abs(b.l-M[i-1].c)):b.h-b.l),s=0;for(let i=0;i<N;i++){if(i<n){s+=tr[i];if(i===n-1)a[i]=s/n}else a[i]=(a[i-1]*(n-1)+tr[i])/n}return a}const A=atr();let AA=Array(N).fill(null);for(let i=60;i<N;i++){let s=0;for(let k=i-50;k<i;k++)s+=A[k]||0;AA[i]=s/50}
function run(p,lo=60,hi=N-2){let out=[],o=null;for(let i=lo;i<=hi;i++){if(o){const b=M[i];let px=null;if(b.l<=o.sl)px=o.sl;else if(b.h>=o.tp)px=o.tp;if(px==null&&i-o.ei>=12)px=b.c;if(px!=null){out.push({...o,xi:i,r:(px-o.en)/(o.en-o.sl)});o=null}continue}if(!A[i]||!AA[i])continue;const prev=M[i-1],b=M[i],pr=prev.h-prev.l,pb=Math.abs(prev.c-prev.o),br=b.h-b.l;if(pr<=0||br<=0)continue;if(prev.c>=prev.o)continue; // BUY only: failed bearish expansion
if(pr/A[i]<p.big||pb/pr<p.impBody)continue;if(!(b.c>prev.o&&b.h>prev.h-p.reclaim*A[i]))continue; // stronger reclaim: close back above impulse open
const revBody=(b.c-b.o)/br,closePos=(b.c-b.l)/br;if(b.c<=b.o||revBody<p.revBody||closePos<p.closePos)continue;const ar=A[i]/AA[i];if(ar<p.atrMin||ar>p.atrMax)continue;const h=new Date(b.t).getUTCHours();if(p.block.has(h))continue;const en=M[i+1].o,r=A[i];o={en,sl:en-r,tp:en+p.rr*r,ei:i+1,et:M[i+1].t}}
return out}
function st(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,ml=0;for(const x of a){e+=x.r;if(x.r>0){gp+=x.r;w++;ls=0}else{gl+=-x.r;ls++;ml=Math.max(ml,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:99,net:e,dd,ls:ml}}
const hours=[new Set(),new Set([0,1,2,3,4,5]),new Set([20,21,22,23]),new Set([6,7,8]),new Set([16,17,18,19])],C=[];
for(const big of[1.1,1.2,1.3,1.5])for(const impBody of[.55,.6,.65,.7])for(const reclaim of[.05,.15,.3])for(const revBody of[.25,.4,.55])for(const closePos of[.65,.75,.85])for(const atrMin of[.75,1])for(const atrMax of[1.5,2])for(const rr of[1,1.25,1.5])for(const block of hours){const p={big,impBody,reclaim,revBody,closePos,atrMin,atrMax,rr,block},d=st(run(p,60,S-2));if(d.n<25)continue;let score=d.net-d.dd+Math.max(0,d.wr-50)*.35+Math.min(d.pf,2)*3;C.push({p,d,score})}
C.sort((a,b)=>b.score-a.score);console.log('FAILED MOVE BUY — QUALITY OPTIMIZER');console.log(`M5=${N} DEV=${S} HOLD=${N-S} candidates=${C.length}`);console.log('\n🏆 TOP 30 DEV');C.slice(0,30).forEach((x,k)=>console.log(`${k+1} | BIG${x.p.big} IB${x.p.impBody} REC${x.p.reclaim} RB${x.p.revBody} CP${x.p.closePos} ATR${x.p.atrMin}-${x.p.atrMax} RR${x.p.rr} BLOCK[${[...x.p.block]}] | T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)}R DD${x.d.dd.toFixed(2)} LS${x.d.ls}`));
console.log('\n🔐 HOLDOUT TOP 20');C.slice(0,20).forEach((x,k)=>{const h=st(run(x.p,S,N-2));console.log(`${k+1} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} || HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)}R DD${h.dd.toFixed(2)} | BIG${x.p.big} IB${x.p.impBody} REC${x.p.reclaim} RB${x.p.revBody} CP${x.p.closePos} ATR${x.p.atrMin}-${x.p.atrMax} RR${x.p.rr} BLOCK[${[...x.p.block]}]`)});
console.log('\nDo not select by WR alone. Prefer a parameter neighborhood with enough trades, PF/NET surviving HOLD, and controlled DD. Then run walk-forward/monthly/cost validation.');
